@description('Location for all resources')
param location string = resourceGroup().location

@description('Environment name (dev, staging, prod)')
param environmentName string = 'prod'

var openAiAccountName = 'oai-learnai-${environmentName}'
var searchServiceName = 'search-learnai-${environmentName}'

// 1. Provision Azure OpenAI Service Account
resource openAiAccount 'Microsoft.CognitiveServices/accounts@2024-10-01' = {
  name: openAiAccountName
  location: location
  sku: {
    name: 'S0'
  }
  kind: 'OpenAI'
  properties: {
    customSubDomainName: openAiAccountName
    publicNetworkAccess: 'Enabled' // In production, set to Disabled and attach Private Endpoints
    disableLocalAuth: true         // Enforce Azure Managed Identity; disable static API keys
  }
}

// 2. Deploy GPT-4o Model onto OpenAI Account
resource gpt4oDeployment 'Microsoft.CognitiveServices/accounts/deployments@2024-10-01' = {
  parent: openAiAccount
  name: 'gpt-4o'
  sku: {
    name: 'Standard'
    capacity: 30 // 30K Tokens Per Minute (TPM)
  }
  properties: {
    model: {
      format: 'OpenAI'
      name: 'gpt-4o'
      version: '2024-08-06'
    }
    versionUpgradeOption: 'OnceNewDefaultVersionAvailable'
  }
}

// 3. Provision Azure AI Search with Semantic Ranker
resource searchService 'Microsoft.Search/searchServices@2024-06-01-preview' = {
  name: searchServiceName
  location: location
  sku: {
    name: 'standard'
  }
  properties: {
    semanticSearch: 'standard' // Enables cross-encoder semantic reranker
    publicNetworkAccess: 'Enabled'
    authOptions: {
      aadOrApiKey: {
        aadAuthFailureMode: 'http401WithBearerChallenge'
      }
    }
  }
}

output openAiEndpoint string = openAiAccount.properties.endpoint
output searchEndpoint string = 'https://${searchServiceName}.search.windows.net'
